parameters.jsCode:
const inputData = $input.first().json;

const workflowName = inputData.workflow?.name || 'Workflow Desconhecido';
const executionId = inputData.execution?.id || 'N/A';
const nodeName = inputData.execution?.error?.node?.name || 'Node Desconhecido';
const errorMessage = inputData.execution?.error?.message || 'Erro sem mensagem explícita';

const payloadAlerta = '🚨 *ALERTA RADAR SHOPEE - FALHA NO FLUXO* 🚨\n\n' +
  '📌 *Workflow:* ' + workflowName + '\n' +
  '⚙️ *Nó:* ' + nodeName + '\n' +
  '🆔 *Execução:* ' + executionId + '\n\n' +
  '💥 *Erro:* ' + errorMessage.substring(0, 300) + '\n\n' +
  '🕒 *Data/Hora:* ' + new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{
  json: {
    workflow: workflowName,
    status: 'erro',
    erro: errorMessage,
    detalhes: inputData.execution?.error || {},
    texto_alerta: payloadAlerta,
    admin_chat_id: $env.TELEGRAM_ADMIN_CHAT_ID
  }
}];

